def build_text_payload(
    prompt: str,
    *,
    model: str,
    instructions: Optional[str] = None,
    max_output_tokens: Optional[int] = None,
    temperature: Optional[float] = None,
    top_p: Optional[float] = None,
    store: bool = False,
    metadata: Optional[Mapping[str, str]] = None,
    extra: Optional[Mapping[str, Any]] = None,
) -> dict[str, Any]:
    """Build a Responses API body for one private text prompt."""
    if not isinstance(prompt, str) or prompt == "":
        raise ValueError("prompt must be a non-empty string")
    if not isinstance(model, str) or model == "":
        raise ValueError("model must be a non-empty string")
    if not isinstance(store, bool):
        raise ValueError("store must be a bool")
    payload: dict[str, Any] = {
        "model": model,
        "input": prompt,
        "store": store,
    }
    if instructions is not None:
        if not isinstance(instructions, str):
            raise ValueError("instructions must be a string")
        payload["instructions"] = instructions
    if max_output_tokens is not None:
        if not isinstance(max_output_tokens, int) or isinstance(max_output_tokens, bool) or max_output_tokens < 1:
            raise ValueError("max_output_tokens must be a positive integer")
        payload["max_output_tokens"] = max_output_tokens
    if temperature is not None:
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)):
            raise ValueError("temperature must be a number")
        payload["temperature"] = temperature
    if top_p is not None:
        if isinstance(top_p, bool) or not isinstance(top_p, (int, float)):
            raise ValueError("top_p must be a number")
        payload["top_p"] = top_p
