def extract_output_text(response: Mapping[str, Any]) -> str:
    """Return assistant text. Raises RefusalError if the model refused."""
    direct = response.get("output_text")
    if isinstance(direct, str):
        return direct
    parts: list[str] = []
    output = response.get("output") or []
    if not isinstance(output, list):
        raise OpenAIError("Response output has an unexpected shape.")
    for item in output:
        if not isinstance(item, dict):
            continue
        item_type = item.get("type")
        if item_type == "output_text" and isinstance(item.get("text"), str):
            parts.append(item["text"])
            continue
        if item_type != "message":
