class OpenAIClient:
    """Minimal Responses API client for confidential text prompts.

    The API key is read from the ``api_key`` argument or ``OPENAI_API_KEY``.
    It is kept off ``repr`` and is stripped from errors. There is no command-line
    entry point, so prompts are not exposed in process arguments.
    """

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        base_url: Optional[str] = None,
        timeout: float = 120.0,
        organization: Optional[str] = None,
        project: Optional[str] = None,
        max_retries: int = 0,
    ) -> None:
        key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY")
        if not key or not str(key).strip():
            raise OpenAIError("Missing API key. Pass api_key or set OPENAI_API_KEY.")
        if not isinstance(max_retries, int) or isinstance(max_retries, bool) or max_retries < 0:
            raise ValueError("max_retries must be a non-negative integer")
        if isinstance(timeout, bool) or not isinstance(timeout, (int, float)) or timeout <= 0:
            raise ValueError("timeout must be a positive number")
        self._api_key = str(key)
        resolved = base_url if base_url is not None else os.environ.get("OPENAI_BASE_URL", DEFAULT_BASE_URL)
        self.base_url = _validate_base_url(resolved)
        self.timeout = float(timeout)
        self.organization = organization if organization is not None else os.environ.get("OPENAI_ORG_ID")
        self.project = project if project is not None else os.environ.get("OPENAI_PROJECT_ID")
        self.max_retries = max_retries
        self._ssl_context = ssl.create_default_context()
        self._ssl_context.minimum_version = ssl.TLSVersion.TLSv1_2

    def __repr__(self) -> str:
        return "OpenAIClient(base_url=%r, timeout=%r, max_retries=%r)" % (
            self.base_url,
            self.timeout,
            self.max_retries,
        )

    def send_text(
        self,
        prompt: str,
        *,
        model: str,
        instructions: Optional[str] = None,
        max_output_tokens: Optional[int] = None,
        temperature: Optional[float] = None,
        top_p: Optional[float] = None,
        store: bool = False,
        metadata: Optional[Mapping[str, str]] = None,
        extra: Optional[Mapping[str, Any]] = None,
        timeout: Optional[float] = None,
    ) -> str:
        """Send one text prompt and return the assistant text.

        ``store`` defaults to false. Pass ``store=True`` only if later retrieval
        of this response is required; that retains the exchange for API retrieval.
        ``model`` is required so this module does not guess a model.
        """
        payload = build_text_payload(
            prompt,
            model=model,
            instructions=instructions,
            max_output_tokens=max_output_tokens,
            temperature=temperature,
            top_p=top_p,
            store=store,
            metadata=metadata,
            extra=extra,
        )
        response = self.create_response(payload, timeout=timeout, secrets=_secrets(payload, self._api_key))
        return _text_from_completed(response)

    def create_response(
        self,
        payload: Mapping[str, Any],
        *,
        timeout: Optional[float] = None,
        secrets: Optional[Sequence[str]] = None,
    ) -> dict[str, Any]:
        """POST a Responses request. Missing ``store`` is set to false.

        Timeouts are not retried, because the server may already have received
        the prompt. ``max_retries`` applies only to connection failures before a
        response and to retryable HTTP statuses.
        """
        if not isinstance(payload, Mapping):
            raise ValueError("payload must be a mapping")
        body = dict(payload)
        body.setdefault("store", False)
        if not isinstance(body.get("store"), bool):
            raise ValueError("store must be a bool")
        hidden = list(secrets) if secrets is not None else _secrets(body, self._api_key)
        encoded = json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        request = self._request(encoded)
        endpoint_timeout = self.timeout if timeout is None else timeout
        if isinstance(endpoint_timeout, bool) or not isinstance(endpoint_timeout, (int, float)) or endpoint_timeout <= 0:
            raise ValueError("timeout must be a positive number")
        opener = urllib.request.build_opener(_RejectRedirects(), urllib.request.HTTPSHandler(context=self._ssl_context))
        attempt = 0
        while True:
            try:
                with opener.open(request, timeout=float(endpoint_timeout)) as response:
                    raw = response.read()
                    status = getattr(response, "status", None)
                    headers = getattr(response, "headers", None)
            except OpenAIError:
                raise
            except urllib.error.HTTPError as exc:
                status = exc.code
                headers = exc.headers
                raw = exc.read(_MAX_ERROR_BYTES)
                if status in _RETRYABLE_STATUS and attempt < self.max_retries:
                    self._sleep_before_retry(attempt, headers)
                    attempt += 1
                    continue
                self._raise_http_error(status, headers, raw, hidden)
            except urllib.error.URLError as exc:
                reason = exc.reason
                timed_out = isinstance(reason, (TimeoutError, socket.timeout))
                if not timed_out and attempt < self.max_retries:
                    self._sleep_before_retry(attempt, None)
                    attempt += 1
                    continue
                detail = _clip(_redact(str(reason), hidden))
                label = "Request timed out" if timed_out else "Request failed before a response"
                raise OpenAIError("%s: %s" % (label, detail)) from None
            except (TimeoutError, socket.timeout):
                raise OpenAIError("Request timed out.") from None
            else:
                return self._parse_success(raw, status, headers, hidden)

    def _request(self, encoded: bytes) -> urllib.request.Request:
        headers = {
            "Authorization": "Bearer %s" % self._api_key,
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "python-stdlib-openai-responses/1.0",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project
        return urllib.request.Request(
            self.base_url + "/responses",
            data=encoded,
            headers=headers,
            method="POST",
        )

    def _sleep_before_retry(self, attempt: int, headers: Optional[Any]) -> None:
        delay = min(2.0 ** attempt, 30.0)
        retry_after = _header(headers, "Retry-After")
        if retry_after is not None:
            try:
                delay = min(float(retry_after), 30.0)
            except ValueError:
                pass
        time.sleep(delay)

    def _raise_http_error(
        self,
        status: int,
        headers: Optional[Any],
        raw: bytes,
        secrets: Sequence[str],
    ) -> None:
        request_id = _header(headers, "x-request-id")
        message = "Responses API request failed (HTTP %s)." % status
        error_type = None
        parsed = _decode_json(raw)
        if isinstance(parsed, dict):
            error = parsed.get("error")
            if isinstance(error, dict):
                error_type = error.get("type") if isinstance(error.get("type"), str) else None
                api_message = error.get("message")
                if isinstance(api_message, str) and api_message:
                    message = _clip(_redact(api_message, secrets))
        raise OpenAIError(message, status_code=status, request_id=request_id, error_type=error_type)

    def _parse_success(
        self,
        raw: bytes,
        status: Optional[int],
        headers: Optional[Any],
        secrets: Sequence[str],
    ) -> dict[str, Any]:
        parsed = _decode_json(raw)
        if not isinstance(parsed, dict):
            raise OpenAIError(
                "Responses API returned a non-object body.",
                status_code=status,
                request_id=_header(headers, "x-request-id"),
            )
        if status is not None and status >= 400:
            self._raise_http_error(status, headers, raw, secrets)
        return parsed


def send_text(
    prompt: str,
    *,
    model: str,
    api_key: [REDACTED_SECRET] = None,
    **kwargs: Any,
) -> str:
    """Send one private text prompt with a short-lived client."""
    client_keys = {"base_url", "timeout", "organization", "project", "max_retries"}
    client_kwargs = {key: kwargs.pop(key) for key in list(kwargs) if key in client_keys}
    return OpenAIClient(api_key=[REDACTED_SECRET] **client_kwargs).send_text(prompt, model=model, **kwargs)


def _secrets(payload: Mapping[str, Any], api_key: str) -> list[str]:
    values = [api_key, "Bearer %s" % api_key]
    for key in ("input", "instructions"):
        value = payload.get(key)
        if isinstance(value, str):
            values.append(value)
    return values


def _decode_json(raw: bytes) -> Any:
    if not raw:
        return None
    try:
        return json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None


def _text_from_completed(response: Mapping[str, Any]) -> str:
    status = response.get("status")
    error = response.get("error")
    if isinstance(error, dict) and status in {"failed", "incomplete"}:
        api_message = error.get("message")
        message = api_message if isinstance(api_message, str) and api_message else "Responses API returned an error."
        if status == "incomplete":
            text = ""
            try:
                text = extract_output_text(response)
            except RefusalError:
                raise
            except OpenAIError:
                text = ""
            raise IncompleteResponseError(message, text=text, error_type=error.get("code") if isinstance(error.get("code"), str) else None)
        raise OpenAIError(message, error_type=error.get("code") if isinstance(error.get("code"), str) else None)
    if status == "incomplete":
        text = ""
        try:
            text = extract_output_text(response)
        except RefusalError:
            raise
        except OpenAIError:
            text = ""
        raise IncompleteResponseError("Response incomplete.", text=text)
    if status not in {None, "completed"}:
        raise OpenAIError("Response was not completed (status: %s)." % status)
    try:
        return extract_output_text(response)
    except RefusalError:
        raise
    except OpenAIError:
        raise OpenAIError("Completed response did not include output text.") from None


